double AraHost::progress()const{double sum=0;size_t count=0;for(auto&pair:impl->sources)if(pair.second&&pair.second->analysis){sum+=pair.second->progress;count++;}return count?sum/count:-1;}
AraTransportRequest AraHost::takeTransport(){auto request=impl->transport;impl->transport={};return request;}
